-- ── competition_provider_map: espn liga_id -> competition_id (compmap_v1), from agenda ──
insert into v2.competition_provider_map (provider, provider_competition_id, competition_id, competition_label, mapping_version)
select 'espn', liga_id, liga_id, max(liga_nombre), 'compmap_v1'
from public.agenda_espn where deporte='soccer' and liga_id is not null
group by liga_id
on conflict do nothing;
